 static string Inventory(Chunk c){var s=new StringBuilder();foreach(var te in c.GetTileEntities().list){s.Append(te.localChunkPos+" "+te.GetType().Name+" ");var w=te as TileEntityWorkstation;if(w!=null){s.Append("output=");foreach(var i in w.Output)if(!i.IsEmpty())s.Append(i.itemValue.ItemClass.GetItemName()+"="+i.count+";");s.Append(" queue=");foreach(var q in w.Queue)if(q!=null&&q.Recipe!=null)s.Append(q.Recipe.GetName()+"x"+q.Multiplier+";");}var tc=te as TileEntityComposite;var st=tc==null?null:tc.GetFeature<TEFeatureStorage>();if(st!=null)foreach(var i in st.ItemGrid.CloneItems())if(!i.IsEmpty())s.Append(i.itemValue.ItemClass.GetItemName()+"="+i.count+";");s.AppendLine();}return s.ToString();}
 public override void Execute(List<string> args,CommandSenderInfo sender){EntityAlive p=null;try{checks=0;string mode=args.Count==0?"nutrition":args[0];
  if(mode=="audit"||mode=="recover"||mode=="reload"){Recovery(mode);return;}
  if(mode=="activationall"){ActivationAll();return;}
  if(mode=="diagnostic"){foreach(long key in Manager().GetAllChunkKeys()){var c=Manager().GetChunkSync(key);if(c.GetTileEntities().list.Count==0)continue;SdtdConsole.Instance.Output("CHUNK "+c.X+","+c.Z+"\n"+Inventory(c));foreach(var t in c.GetTileEntities().list)SdtdConsole.Instance.Output("BLOCK "+t.localChunkPos+" "+c.GetBlock(t.localChunkPos).Block.GetBlockName());}return;}
  if(mode=="repairrecords"||mode=="auditrecords"){Check(GameIO.GetUserGameDataDir().Replace('\\','/').EndsWith("/BatchNine"),"Disposable profile only");var h=new Harmony("delve.batch9.records");var method=AccessTools.Method(typeof(TileEntityComposite),"read",new[]{typeof(PooledBinaryReader),typeof(StreamModeRead),typeof(int[])});h.Patch(method,new HarmonyMethod(typeof(ConsoleCmdBatchNine).GetMethod("CompositeRead",BindingFlags.Static|BindingFlags.NonPublic)));try{var dirty=new HashSet<Chunk>();int missing=0;foreach(long key in Manager().GetAllChunkKeys()){var c=Manager().GetChunkSync(key);for(int y=0;y<256;y++)for(int z=0;z<16;z++)for(int x=0;x<16;x++){var b=c.GetBlock(x,y,z);if(b.ischild||!(b.Block is BlockWorkstation))continue;var pos=new Vector3i(x,y,z);var te=c.GetTileEntity(pos);if(te is TileEntityWorkstation)continue;Check(te==null,"Do not replace existing station inventory");string id=c.X+","+c.Z+":"+x+","+y+","+z;Check(id=="-177,-131:11,67,1"||id=="-169,-135:8,66,10"||id=="-168,-140:4,67,4","Unexpected missing station "+id);SdtdConsole.Instance.Output("MISSING STATION "+id+" "+b.Block.GetBlockName()+" has no saved tile entity");if(mode=="repairrecords"){var station=new TileEntityWorkstation(c);station.localChunkPos=pos;c.AddTileEntity(station);dirty.Add(c);}missing++;}if(compositeRepairs.Contains(c)){SdtdConsole.Instance.Output("RESTORED CONTAINER CONTENTS "+c.X+","+c.Z+"\n"+Inventory(c));dirty.Add(c);}}if(mode=="repairrecords"){foreach(var c in dirty){c.isModified=true;Manager().SaveChunkSnapshot(c,true);}Manager().WaitSaveDone();}SdtdConsole.Instance.Output("[Batch09Records] PASS "+mode+" missing="+missing+" compositeChunks="+compositeRepairs.Count+" dirty="+dirty.Count);}finally{h.Unpatch(method,HarmonyPatchType.All,h.Id);}return;}
  if(mode=="allchunks"){var manager=Manager();int count=0,stations=0;var missing=new StringBuilder();foreach(long key in manager.GetAllChunkKeys()){var chunk=manager.GetChunkSync(key);Check(chunk!=null,"Saved chunk loads "+key);count++;for(int y=0;y<256;y++)for(int z=0;z<16;z++)for(int x=0;x<16;x++){var b=chunk.GetBlock(x,y,z);if(b.ischild||!(b.Block is BlockWorkstation))continue;stations++;if(!(chunk.GetTileEntity(new Vector3i(x,y,z)) is TileEntityWorkstation))missing.AppendLine(chunk.X+","+chunk.Z+" local "+x+","+y+","+z+" "+b.Block.GetBlockName());}}Check(missing.Length==0,"Workstations missing tile entities:\n"+missing);SdtdConsole.Instance.Output("[Batch09AllChunks] PASS "+count+" saved chunks load; all "+stations+" workstation blocks have their saved tile entities.");return;}
  Check(Harmony.GetPatchInfo(AccessTools.Method(typeof(TileEntityWorkstation),"read")).Owners.Contains("delve.livingborder"),"Station reader patched");Check(Harmony.GetPatchInfo(AccessTools.Method(typeof(TileEntityWorkstation),"write")).Owners.Contains("delve.livingborder"),"Station writer patched");Check(Core.Progress!=null,"Core initialization completed");
  p=EntityFactory.CreateEntity(EntityClass.FromString("playerMale"),Vector3.zero) as EntityAlive;p.world=GameManager.Instance.World;
  foreach(string n in new[]{"foodDelveBrambleberries","foodDelveCookedBerries"}){int value=n=="foodDelveBrambleberries"?2:5;var item=ItemClass.GetItem(n,false);foreach(string v in new[]{"$foodAmountAdd","$waterAmountAdd","$healthAmountAdd"})p.Buffs.SetCustomVar(v,0);int health=p.Health;item.ItemClass.FireEvent(MinEventTypes.onSelfPrimaryActionEnd,new MinEventParams{Self=p,ItemValue=item});Check(p.Buffs.GetCustomVar("$foodAmountAdd")==value,n+" food");Check(p.Buffs.GetCustomVar("$waterAmountAdd")==value,n+" water");Check(p.Buffs.GetCustomVar("$healthAmountAdd")==0&&p.Health==health,n+" zero health");}
  // Actual native station serializer must preserve stream boundaries and credits.
  foreach(StreamModeWrite modeWrite in new[]{(StreamModeWrite)0,(StreamModeWrite)1,(StreamModeWrite)2}){var station=new TileEntityWorkstation((Chunk)null);station.SetDisableModifiedCheck(true);Rank20StationCredits.Data.GetOrCreateValue(station).Fuel=.25f;Rank20StationCredits.Data.GetOrCreateValue(station).Extraction=.5f;var ms=new MemoryStream();var w=new PooledBinaryWriter();w.SetBaseStream(ms);station.write(w,modeWrite);w.Write(123456789);w.Flush();ms.Position=0;var r=new PooledBinaryReader();r.SetBaseStream(ms);var loaded=new TileEntityWorkstation((Chunk)null);loaded.SetDisableModifiedCheck(true);loaded.read(r,(StreamModeRead)(int)modeWrite);Check(r.ReadInt32()==123456789,"Stream boundary "+modeWrite);var c=Rank20StationCredits.Data.GetOrCreateValue(loaded);Check(c.Fuel==.25f&&c.Extraction==.5f,"Maker credits "+modeWrite);}
  SdtdConsole.Instance.Output("[Batch09] PASS "+checks+" checks; 3.4 core startup; station serialization boundaries; raw berries 2/2/0, cooked berries 5/5/0.");
 }catch(Exception e){SdtdConsole.Instance.Output("[Batch09] FAIL "+e);}finally{if(p!=null)UnityEngine.Object.Destroy(p.gameObject);}}
 static void ActivationAll(){var h=new Harmony("delve.batch9.allactivation");var tile=AccessTools.Method(typeof(World),"GetTileEntity",new[]{typeof(Vector3i)});var protect=AccessTools.Method(typeof(World),"IsMyLandProtectedBlock",new[]{typeof(Vector3i),typeof(PersistentPlayerData)});var player=EntityFactory.CreateEntity(EntityClass.FromString("playerMale"),Vector3.zero) as EntityAlive;player.world=GameManager.Instance.World;int count=0;h.Patch(tile,new HarmonyMethod(typeof(ConsoleCmdBatchNine).GetMethod("Tile",BindingFlags.Static|BindingFlags.NonPublic)));h.Patch(protect,new HarmonyMethod(typeof(ConsoleCmdBatchNine).GetMethod("Protection",BindingFlags.Static|BindingFlags.NonPublic)));try{foreach(long key in Manager().GetAllChunkKeys()){var c=Manager().GetChunkSync(key);foreach(var te in c.GetTileEntities().list){var w=te as TileEntityWorkstation;if(w==null)continue;Check(w.Input!=null&&w.Output!=null&&w.Queue!=null,"Station arrays initialized");activationTile=w;var b=c.GetBlock(te.localChunkPos);var commands=b.Block.GetBlockActivationCommands(GameManager.Instance.World,b,te.ToWorldPos(),player);Check(commands!=null&&commands.Length>0,"Station native interaction "+b.Block.GetBlockName());count++;}}Check(count==15,"All 15 saved stations tested");SdtdConsole.Instance.Output("[Batch09Activation] PASS native interaction commands for all "+count+" saved stations including the repaired player field mat.");}finally{activationTile=null;h.Unpatch(tile,HarmonyPatchType.All,h.Id);h.Unpatch(protect,HarmonyPatchType.All,h.Id);UnityEngine.Object.Destroy(player.gameObject);}}
 static void Recovery(string mode){Check(GameIO.GetUserGameDataDir().Replace('\\','/').EndsWith("/BatchNine"),"Disposable recovery profile only");Check(GameManager.Instance.World.GetPlayers().Count==0,"No players connected");var manager=Manager();string folder=Path.Combine(ModManager.GetMod("StationProbe",true).Path,"Recovery");var report=new StringBuilder();int restored=0,activation=0;EntityAlive player=EntityFactory.CreateEntity(EntityClass.FromString("playerMale"),Vector3.zero) as EntityAlive;player.world=GameManager.Instance.World;
  var harmony=new Harmony("delve.batch9.activation.fixture");var tileMethod=AccessTools.Method(typeof(World),"GetTileEntity",new[]{typeof(Vector3i)});var protectionMethod=AccessTools.Method(typeof(World),"IsMyLandProtectedBlock",new[]{typeof(Vector3i),typeof(PersistentPlayerData)});harmony.Patch(tileMethod,new HarmonyMethod(typeof(ConsoleCmdBatchNine).GetMethod("Tile",BindingFlags.Static|BindingFlags.NonPublic)));harmony.Patch(protectionMethod,new HarmonyMethod(typeof(ConsoleCmdBatchNine).GetMethod("Protection",BindingFlags.Static|BindingFlags.NonPublic)));
  try{foreach(string file in Directory.GetFiles(folder,"*.uncomp.bak")){string name=Path.GetFileName(file);var parts=name.Split('_');int x=int.Parse(parts[2]),z=int.Parse(parts[3].Split('.')[0]);byte[] comp=File.ReadAllBytes(file.Replace(".uncomp.bak",".comp.bak"));Check(comp[0]==116&&comp[1]==116&&comp[2]==99,"Chunk backup header");uint version=BitConverter.ToUInt32(comp,4);var r=new PooledBinaryReader();var ms=new MemoryStream(File.ReadAllBytes(file));r.SetBaseStream(ms);var recovered=new Chunk(x,z);recovered.load(r,version);Check(ms.Position==ms.Length,"Complete error-backup payload decoded "+name+" "+ms.Position+"/"+ms.Length);long key=WorldChunkCache.MakeChunkKey(x,z);var current=manager.GetChunkSync(key);report.AppendLine("CHUNK "+x+","+z+" version="+version+" backup tile entities="+recovered.GetTileEntities().list.Count+" current="+(current==null?-1:current.GetTileEntities().list.Count));report.AppendLine("RECOVERED INVENTORY\n"+Inventory(recovered));if(current!=null)report.AppendLine("CURRENT INVENTORY\n"+Inventory(current));
   if(mode=="audit"){int diff=0;for(int y=0;y<256;y++)for(int dz=0;dz<16;dz++)for(int dx=0;dx<16;dx++){var b=recovered.GetBlock(dx,y,dz);var a=current==null?BlockValue.Air:current.GetBlock(dx,y,dz);if(a.rawData==b.rawData&&a.damage==b.damage)continue;diff++;if(diff<120)report.AppendLine("DIFF "+dx+","+y+","+dz+" current="+a.Block.GetBlockName()+" backup="+b.Block.GetBlockName());}report.AppendLine("BLOCK DIFFERENCES="+diff);continue;}
   if(mode=="recover"){recovered.isModified=true;recovered.NeedsRegeneration=true;manager.SaveChunkSnapshot(recovered,true);restored++;}
   else {Check(current!=null,"Recovered chunk loads");Check(Inventory(current)==Inventory(recovered),"Recovered tile contents retained "+name);}
   var target=mode=="recover"?recovered:current;
   // Invoke the real activation method with a world adapter that supplies the
   // loaded tile, without loading terrain around a synthetic player.
   foreach(var te in target.GetTileEntities().list){var station=te as TileEntityWorkstation;if(station==null)continue;Check(station.Input!=null&&station.Output!=null&&station.Queue!=null,"Workstation arrays present");activationTile=station;var pos=te.localChunkPos;var block=target.GetBlock(pos);var commands=block.Block.GetBlockActivationCommands(GameManager.Instance.World,block,te.ToWorldPos(),player);Check(commands!=null&&commands.Length>0,"Native activation commands "+block.Block.GetBlockName());activationTile=null;activation++;}
  }
  if(mode=="recover")manager.WaitSaveDone();report.AppendLine("[Batch09Recovery] PASS mode="+mode+" restored="+restored+" stations="+activation+" checks="+checks);File.WriteAllText(Path.Combine(folder,mode+".txt"),report.ToString());SdtdConsole.Instance.Output(report.ToString());
  }finally{activationTile=null;harmony.Unpatch(tileMethod,HarmonyPatchType.All,harmony.Id);harmony.Unpatch(protectionMethod,HarmonyPatchType.All,harmony.Id);UnityEngine.Object.Destroy(player.gameObject);}
 }
